+#!/usr/bin/env node
+const { execSync } = require('child_process');
+const fs = require('fs');
+
+// Configurable thresholds
+const GAP_SEVERITY_THRESHOLD = process.env.GAP_SEVERITY || 3; // 1-5 scale, higher is critical
+const STALENESS_THRESHOLD = process.env.STALENESS_DAYS || 7; // Days before gap is critical
+
+// Fetch gaps from city-brief
+const gaps = JSON.parse(execSync('node .fastops/city-brief.js --gaps', { encoding: 'utf8' }));
+
+// Filter gaps based on thresholds
+const criticalGaps = gaps.filter(gap => 
+  gap.severity >= GAP_SEVERITY_THRESHOLD && gap.staleness >= STALENESS_THRESHOLD
+);
+
+// Process each critical gap
+criticalGaps.forEach(gap => {
+  console.log(`Dispatching task for gap: ${gap.id} (Severity: ${gap.severity}, Staleness: ${gap.staleness})`);
+  
+  // Dispatch task using city-session
+  const dispatchCmd = `node .fastops/city-session.js --task "Address gap ${gap.id}: ${gap.description}" --model ${gap.suggestedModel || 'default'}`;
+  const dispatchResult = execSync(dispatchCmd, { encoding: 'utf8' });
+  
+  // Log action to city-ledger
+  const logEntry = {
+    timestamp: new Date().toISOString(),
+    action: 'dispatch',
+    gapId: gap.id,
+    task: `Address gap ${gap.id}`,
+    result: dispatchResult.trim()
+  };
+  fs.appendFileSync('.fastops/city-ledger.json', JSON.stringify(logEntry) + '\n');
+});
+
+if (criticalGaps.length === 0) {
+  console.log('No critical gaps detected above thresholds.');
+}
